   142	        let collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
   143	        while (collisions.length) {
   144	          bounds.column = Math.max(...collisions.map((other) => other.column + other.columns + box.layout.gap));
   145	          collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
   146	        }
   147	        settled.push(bounds);
